-- 1: houyi-control-valve-4mm
UPDATE products SET
  name = 'HOUYI صمام تحكم بالهواء دقيق - ضبط تدفق سلس | 4 ملم',
  description = E'صمام تحكم يُركّب على خرطوم الهواء لضبط كمية الهواء المتدفقة بدقة عالية. التصميم الدوّار يسمح بتقليل أو زيادة التدفق بسلاسة تامة.\n\nضروري عند استخدام مضخة هواء قوية مع حجر هواء صغير - بدون صمام التحكم تكون الفقاعات قوية جداً وتزعج الأسماك.\n\nبلاستيك متين مقاوم للمياه. متوافق مع جميع خراطيم الهواء بقطر 4 ملم.',
  specifications = '{"brand":"HOUYI","model":"Control Valve 4mm","benefits":["ضبط دقيق لكمية الهواء المتدفقة","تصميم دوّار سلس وسهل الاستخدام","يقلل قوة الفقاعات المفرطة","بلاستيك متين مقاوم للمياه","متوافق مع خراطيم 4 ملم القياسية","ضروري لتوازن التهوية"],"المادة":"بلاستيك متين","القطر":"4 ملم","النوع":"صمام تحكم دوّار","مناسب لـ":"ضبط تدفق الهواء في أحجار الهواء والفلاتر","بلد المنشأ":"الصين","طريقة الاستخدام":"اقطع خرطوم الهواء في الموضع المناسب. أدخل طرفي الصمام في الخرطوم. أدر المقبض للتحكم بكمية الهواء.","تحذيرات":"لا تغلق الصمام بالكامل أثناء تشغيل المضخة - يزيد الضغط ويتلفها. استبدله إذا أصبحت الحركة صعبة."}'::jsonb
WHERE id = 'houyi-control-valve-4mm';

-- 2: houyi-chubby-thermometer
UPDATE products SET
  name = 'HOUYI ميزان حرارة عائم كلاسيكي (Chubby) - دقة الزجاج التقليدي',
  description = E'ميزان حرارة زجاجي عائم بتصميم كلاسيكي قصير وسمين (Chubby) سهل القراءة. يطفو عمودياً في الماء ويُظهر درجة الحرارة بمقياس واضح ومرقّم.\n\nدقة الزجاج التقليدي تتفوق على الشرائط اللاصقة الرخيصة التي تعطي قراءات تقريبية فقط. لا يحتاج بطارية ولا يتلف مع الماء.\n\nتصميمه القصير والممتلئ يجعله أكثر مقاومة للكسر من الموازين الرفيعة الطويلة.',
  specifications = '{"brand":"HOUYI","model":"Chubby Thermometer","benefits":["دقة زجاجية تقليدية تتفوق على الشرائط","تصميم قصير وسمين مقاوم للكسر","يطفو عمودياً لقراءة سهلة","لا يحتاج بطارية أو كهرباء","مقياس واضح ومرقّم","يدوم لسنوات بدون صيانة"],"النوع":"ميزان حرارة زجاجي عائم","التصميم":"Chubby (قصير وسمين)","نطاق القياس":"0-40°C","الدقة":"±0.5°C","مناسب لـ":"جميع أنواع الأحواض","بلد المنشأ":"الصين","طريقة الاستخدام":"ضعه في الماء بعيداً عن السخان ومخرج الفلتر. اقرأ الحرارة بعد 5 دقائق من الاستقرار. يبقى عائماً دائماً.","تحذيرات":"زجاجي - تعامل بحذر. أبعده عن الأسماك القوية التي قد تصطدم وتكسره. إذا انكسر أخرج القطع فوراً."}'::jsonb
WHERE id = 'houyi-chubby-thermometer';

-- 3: houyi-led
UPDATE products SET
  name = 'HOUYI ميزان حرارة LED رقمي - قراءة دقيقة خلال دقيقة',
  description = E'ميزان حرارة رقمي بمستشعر مقاوم للماء وشاشة LED واضحة. يعطي قراءة دقيقة لدرجة حرارة الماء خلال دقيقة واحدة.\n\nالمستشعر يُغمر في الماء بينما تبقى الشاشة خارج الحوض لسهولة القراءة من أي زاوية. أرقام كبيرة وواضحة يمكن قراءتها من مسافة.\n\nيعمل بالبطارية ويدوم لأشهر. أسهل في القراءة من الموازين الزجاجية التقليدية خاصة في الإضاءة الخافتة.',
  specifications = '{"brand":"HOUYI","model":"LED Thermometer","benefits":["شاشة LED رقمية واضحة وكبيرة","مستشعر مقاوم للماء دقيق","قراءة خلال دقيقة واحدة","يمكن قراءته من مسافة وفي الإضاءة الخافتة","يعمل بالبطارية - يدوم أشهر","أسهل من الموازين الزجاجية"],"النوع":"ميزان حرارة رقمي LED","نطاق القياس":"0-50°C","الدقة":"±0.1°C","الطاقة":"بطارية (مرفقة)","مناسب لـ":"جميع أنواع الأحواض","بلد المنشأ":"الصين","طريقة الاستخدام":"اغمر طرف المستشعر في الماء. ثبّت الشاشة خارج الحوض بالماصة. انتظر دقيقة للقراءة الدقيقة.","تحذيرات":"لا تغمر الشاشة في الماء - فقط المستشعر. استبدل البطارية عند ضعف الشاشة. تأكد من سلامة عزل سلك المستشعر."}'::jsonb
WHERE id = 'houyi-led';

-- 4: houyi-terminalia-leaves
UPDATE products SET
  name = 'HOUYI أوراق الكاتابا الطبيعية (Terminalia) - مضاد حيوي طبيعي للأحواض',
  description = E'أوراق شجرة اللوز الهندي (Terminalia catappa) المجففة طبيعياً. تطلق التانين والمواد المضادة للبكتيريا والفطريات في الماء، مما يوفر بيئة شبيهة بالموطن الطبيعي للأسماك الاستوائية.\n\nمفضلة لأسماك البيتا والديسكس والروبيان. التانين يخفض pH قليلاً ويعطي الماء لوناً بنياً دافئاً يحاكي مياه الأنهار الاستوائية ويقلل إجهاد الأسماك.\n\nتوفر أيضاً سطحاً لنمو البيوفيلم الذي يتغذى عليه الروبيان وصغار الأسماك. بديل طبيعي آمن للمعالجات الكيميائية.',
  specifications = '{"brand":"HOUYI","model":"Terminalia Leaves","benefits":["مضاد حيوي طبيعي مضاد للبكتيريا والفطريات","تطلق تانين يحاكي البيئة الاستوائية","تخفض pH قليلاً وتقلل إجهاد الأسماك","توفر بيوفيلم يتغذى عليه الروبيان","بديل طبيعي آمن للمعالجات الكيميائية","مفضلة للبيتا والديسكس والروبيان"],"النوع":"أوراق طبيعية مجففة","المصدر":"Terminalia catappa (اللوز الهندي)","التأثير":"يخفض pH، مضاد بكتيري/فطري","مناسب لـ":"أحواض البيتا، الديسكس، الروبيان، البيوتوب","بلد المنشأ":"الصين","طريقة الاستخدام":"ضع ورقة واحدة لكل 20-30 لتر ماء. ستنزل للقاع خلال يوم. ستبدأ بالتحلل ببطء وتطلق المواد المفيدة. استبدلها كل 2-3 أسابيع.","تحذيرات":"ستصبغ الماء بلون بني/عسلي - طبيعي ومفيد. استخدم الكربون النشط إذا لم ترغب في اللون. لا تفرط في الكمية."}'::jsonb
WHERE id = 'houyi-terminalia-leaves';

-- 5: houyi-inflatable-fish-bag
UPDATE products SET
  name = 'HOUYI أكياس نقل الأسماك الهوائية - بلاستيك سميك مقاوم للثقب',
  description = E'أكياس نقل أسماك احترافية مصنوعة من بلاستيك سميك مزدوج الطبقة (Double Layer). قاعدة مدورة تمنع انحسار السمكة في الزوايا الحادة وتوفر حماية أفضل.\n\nتحافظ على الأوكسجين لفترات طويلة مقارنة بالأكياس العادية. مقاومة للثقب والتمزق أثناء النقل والشحن.\n\nمتوفرة بأحجام متعددة لتناسب أحجام الأسماك المختلفة. مناسبة للمحلات ومربّي الأسماك الذين يشحنون بانتظام.',
  specifications = '{"brand":"HOUYI","model":"Inflatable Fish Bag","benefits":["بلاستيك سميك مزدوج الطبقة (Double Layer)","قاعدة مدورة تحمي الأسماك من الزوايا","تحافظ على الأوكسجين لفترات طويلة","مقاومة للثقب والتمزق","متوفرة بأحجام متعددة","مناسبة للنقل والشحن الطويل"],"السماكة":"High Gauge Polyethylene","التصميم":"Round Bottom (قاعدة مدورة)","الحجم":"متعدد","مناسب لـ":"نقل الأسماك، الشحن، المحلات","بلد المنشأ":"الصين","طريقة الاستخدام":"املأ ثلث الكيس بالماء. ضع السمكة بلطف. انفخ الهواء فوق الماء. أغلق بإحكام بحلقات مطاطية.","تحذيرات":"لا تترك الأسماك في الأكياس أكثر من 24 ساعة. حافظ على الحرارة بلف الكيس بصحيفة أو صندوق ستايروفوم. لا تعرّض لأشعة الشمس."}'::jsonb
WHERE id = 'houyi-inflatable-fish-bag';

-- 6: houyi-gauze-isolation-net
UPDATE products SET
  name = 'HOUYI شبكة عزل وتفريخ قماشية - تدفق ماء عالي | مع ماصات تثبيت',
  description = E'شبكة عزل قماشية ناعمة بهيكل بلاستيكي قابل للتجميع وماصات تثبيت قوية. القماش الشبكي يسمح بتدفق الماء بحرية مما يضمن تجدد المياه باستمرار داخل منطقة العزل.\n\nمناسبة لعزل إناث الأسماك الحوامل لحماية المواليد، وعزل أسماك مريضة أو شرسة داخل الحوض الرئيسي. الشبكة ناعمة ولا تجرح الأسماك.\n\nالتدفق العالي للماء يحافظ على نفس درجة حرارة وكيمياء الحوض الرئيسي داخل منطقة العزل، مما يقلل إجهاد الأسماك المعزولة.',
  specifications = '{"brand":"HOUYI","model":"Gauze Isolation Net","benefits":["قماش شبكي ناعم بتدفق ماء عالي","هيكل بلاستيكي قابل للتجميع والفك","ماصات تثبيت قوية تمسك بالزجاج","آمنة للمواليد وصغار الأسماك","نفس حرارة وكيمياء الحوض الرئيسي","مناسبة للعزل والتفريخ والحماية"],"المادة":"Nylon Mesh + Plastic Frame","التركيب":"Suction Cups (ماصات)","الأبعاد":"16×14×15 سم (تقريبي)","اللون":"أبيض","مناسب لـ":"عزل، تفريخ، حماية مواليد، فصل أسماك شرسة","بلد المنشأ":"الصين","طريقة الاستخدام":"جمّع الهيكل البلاستيكي. ركّب الشبكة القماشية. ثبّت بالماصات على زجاج الحوض تحت سطح الماء. ضع السمكة المراد عزلها بلطف.","تحذيرات":"نظّف الشبكة بانتظام لمنع انسداد المسام. لا تكدّس أسماك كثيرة. أزل المواليد بعد الولادة لمنع الأم من أكلهم."}'::jsonb
WHERE id = 'houyi-gauze-isolation-net';

-- 7: houyi-wave-pump
UPDATE products SET
  name = 'HOUYI مضخة أمواج صامتة 3000 لتر/ساعة - تدوير مائي طبيعي',
  description = E'مضخة أمواج كهربائية بتدفق 3000 لتر/ساعة تولّد تيارات مائية تحاكي حركة الأمواج الطبيعية. التيار المائي يمنع ركود الماء ويوزّع الحرارة والأوكسجين بالتساوي في الحوض.\n\nتشغيل صامت بفضل تقنية المغناطيس الدوار. استهلاك كهرباء منخفض رغم قوة التدفق الكبيرة. تثبيت سهل بالماصة على زجاج الحوض.\n\nضرورية للأحواض المرجانية والأحواض الكبيرة. تساعد في منع نمو الطحالب في المناطق الراكدة.',
  specifications = '{"brand":"HOUYI","model":"Wave Pump","benefits":["تدفق قوي 3000 لتر/ساعة","تشغيل صامت بتقنية المغناطيس الدوار","استهلاك كهرباء منخفض","يمنع ركود الماء في الزوايا","يوزّع الحرارة والأوكسجين بالتساوي","يمنع نمو الطحالب في المناطق الراكدة"],"التدفق":"3000 لتر/ساعة","النوع":"مضخة أمواج (Wave Maker)","التثبيت":"ماصة على الزجاج","مناسب لـ":"أحواض كبيرة، أحواض مرجانية، أحواض نباتات","بلد المنشأ":"الصين","طريقة الاستخدام":"ثبّت المضخة بالماصة على زجاج الحوض باتجاه الجانب المقابل. وجّه التدفق لتجنب ضربه المباشر للأسماك. شغّلها باستمرار.","تحذيرات":"لا تشغّل خارج الماء. تأكد من عدم امتصاص صغار الأسماك. نظّف المروحة شهرياً لمنع انخفاض الأداء."}'::jsonb
WHERE id = 'houyi-wave-pump';

-- 8: houyi-hose-brush
UPDATE products SET
  name = 'HOUYI فرشاة تنظيف الخراطيم المرنة - رأسين | 1.55 متر',
  description = E'فرشاة طويلة ومرنة بطول 1.55 متر مصممة لتنظيف خراطيم الفلاتر الخارجية من الداخل. رأسين على طرفي الفرشاة بأحجام مختلفة لتنظيف خراطيم بأقطار متنوعة.\n\nسلك مرن يمر عبر انحناءات الخرطوم بسهولة للوصول لجميع الأجزاء الداخلية. شعيرات متينة تزيل الطحالب والترسبات المتراكمة بفعالية.\n\nأداة ضرورية لصيانة الفلاتر الخارجية التي تعاني من انخفاض التدفق بسبب تراكم الأوساخ في الخراطيم.',
  specifications = '{"brand":"HOUYI","model":"Hose Brush","benefits":["طول 1.55 متر يصل لكامل الخرطوم","رأسين بأحجام مختلفة لأقطار متنوعة","سلك مرن يمر عبر الانحناءات","شعيرات متينة تزيل الطحالب والترسبات","يعيد تدفق الماء الطبيعي للفلتر","أداة ضرورية لصيانة الفلاتر الخارجية"],"الطول":"1.55 متر","الرأس":"Double Ended (رأسين)","مناسب لـ":"تنظيف خراطيم الفلاتر الخارجية","بلد المنشأ":"الصين","طريقة الاستخدام":"ادفع الفرشاة عبر الخرطوم. حرّكها ذهاباً وإياباً لإزالة الترسبات. اشطف الخرطوم بالماء بعد التنظيف.","تحذيرات":"لا تستخدم قوة مفرطة قد تثقب الخرطوم. نظّف الفرشاة بعد كل استخدام. جفّفها لمنع الصدأ."}'::jsonb
WHERE id = 'houyi-hose-brush';

-- 9: houyi-nylon-fishing-net
UPDATE products SET
  name = 'HOUYI شبكة صيد ناعمة - نايلون دقيق آمن للأسماك الصغيرة',
  description = E'شبكة صيد بنايلون ناعم ومقبض سلكي مغلّف. الشبكة الدقيقة مناسبة لالتقاط الأسماك الصغيرة والإصبعيات دون إصابة أو جرح.\n\nحجم مناسب للأحواض الصغيرة والمتوسطة. المقبض المغلّف يوفر قبضة مريحة ويمنع الصدأ.\n\nسهلة الاستخدام للمبتدئين. تُغسل وتجفف بعد كل استخدام للحفاظ عليها.',
  specifications = '{"brand":"HOUYI","model":"Nylon Fishing Net","benefits":["نايلون ناعم ودقيق آمن للأسماك الصغيرة","مقبض سلكي مغلّف مقاوم للصدأ","مناسبة للأحواض الصغيرة والمتوسطة","لا تجرح الأسماك أو تزيل غشاءها المخاطي","سهلة الاستخدام للمبتدئين","خفيفة ومتينة"],"الشبكة":"Fine Nylon (نايلون دقيق)","المقبض":"Coated Wire (سلك مغلّف)","مناسب لـ":"الأسماك الصغيرة والمتوسطة، الإصبعيات","بلد المنشأ":"الصين","طريقة الاستخدام":"بلّل الشبكة قبل الاستخدام. أدخلها في الماء ببطء. حرّك بسلاسة لالتقاط السمكة. انقلها فوراً.","تحذيرات":"بلّل الشبكة دائماً قبل الاستخدام لحماية الغشاء المخاطي. لا تلاحق الأسماك طويلاً. جفّف بعد الاستخدام."}'::jsonb
