-- 10: houyi-feeding-cup
UPDATE products SET
  name = 'HOUYI كوب تغذية الدود الأحمر - مع ماصة تثبيت | أكريليك شفاف',
  description = E'كوب تغذية شفاف مصنوع من الأكريليك مع ماصة تثبيت على زجاج الحوض. مصمم لتقديم الدود الأحمر الحي أو المجمد في مكان محدد دون انتشاره في أنحاء الحوض.\n\nالتصميم المخروطي يسمح للدود بالخروج ببطء مما يعطي الأسماك وقتاً كافياً لالتقاطه. يمنع تلوث الماء بالطعام المتبقي في القاع.\n\nسهل التنظيف وقابل لإعادة الاستخدام. مناسب أيضاً لتقديم الأرتيميا وأطعمة أخرى.',
  specifications = '{"brand":"HOUYI","model":"Feeding Cup","benefits":["يقدم الطعام في مكان محدد ومنظم","يمنع انتشار الدود الأحمر في الحوض","تصميم مخروطي يسمح بخروج الطعام تدريجياً","يقلل تلوث الماء بالطعام المتبقي","أكريليك شفاف لمراقبة كمية الطعام","ماصة تثبيت قوية على الزجاج"],"المادة":"Acrylic / Plastic","التثبيت":"Suction Cup (ماصة)","النوع":"كوب تغذية مخروطي","مناسب لـ":"تقديم الدود الأحمر، الأرتيميا، الأطعمة الحية","بلد المنشأ":"الصين","طريقة الاستخدام":"ثبّت الكوب بالماصة على زجاج الحوض. ضع الدود أو الطعام في الكوب. الأسماك تأكل من الفتحات السفلية.","تحذيرات":"نظّف الكوب بعد كل وجبة لمنع تراكم البقايا. لا تفرط في كمية الطعام. تأكد من ثبات الماصة."}'::jsonb
WHERE id = 'houyi-feeding-cup';

-- 11: houyi-planting-ring
UPDATE products SET
  name = 'HOUYI حلقة تثبيت النباتات المائية (Plant Weight) - رصاص آمن',
  description = E'حلقات رصاص مغلّفة آمنة تُلف حول قاعدة النباتات المائية الحية لمنعها من الطفو. الغلاف يمنع ملامسة الرصاص للماء مباشرة.\n\nمرنة ويمكن ثنيها بسهولة حول أي حجم من السيقان. تبقى مخفية في التربة أو الحصى بعد زراعة النبتة.\n\nحل سريع وفعّال لمشكلة طفو النباتات المائية الشائعة خاصة عند الزراعة الأولى.',
